import{St as e,at as t,it as n,n as r,st as i,vt as a}from"./chunks/framework.B0lbOe_c.js";var o=JSON.parse(`{"title":"Metamodel packages","description":"","frontmatter":{"title":"Metamodel packages","covers":{"screens":[],"stories":["US-033","US-057"]}},"headers":[],"relativePath":"administration/metamodel-packages.md","filePath":"administration/metamodel-packages.md"}`),s={name:`administration/metamodel-packages.md`};function c(r,o,s,c,l,u){let d=e(`Screenshot`);return a(),n(`div`,null,[o[0]||=t(`<h1 id="metamodel-packages" tabindex="-1">Metamodel packages <a class="header-anchor" href="#metamodel-packages" aria-label="Permalink to “Metamodel packages”">​</a></h1><p>A new instance has no entity types. Before anyone can capture entities, you import a metamodel: the shipped starter package or a package of your own.</p><p>Importing packages requires the permission <code>metamodel:write</code>, which only the role <code>metamodel-admin</code> holds – not the local system admin account. Map an IdP group to <code>metamodel-admin</code> (see <a href="./roles-and-permissions">Roles and permissions</a>); as a privileged role, it needs a second factor at the identity provider.</p><h2 id="import-the-starter-configuration" tabindex="-1">Import the starter configuration <a class="header-anchor" href="#import-the-starter-configuration" aria-label="Permalink to “Import the starter configuration”">​</a></h2><p>OEA ships the starter package <code>oea-starter-togaf-classic</code> with the entity types Application Component, Application Service, Data Object, Technology Component, Technology Service, System Software and Network Node, each with the property <em>Status</em>. Version 1.4.0 adds the four <a href="./metamodel-editing#layers">layers</a> <em>Business</em>, <em>Data</em>, <em>Application</em> and <em>Technology</em> with German names and assigns them to the entity types: <em>Application Component</em> and <em>Application Service</em> to Application, <em>Data Object</em> to Data, and <em>Technology Component</em>, <em>Technology Service</em>, <em>System Software</em> and <em>Network Node</em> to Technology (<em>Composition</em> has none). Importing it again into an instance that has an own layer of the same name, for example <em>Business</em>, is refused as a conflict; rename or delete that layer first. Version 1.3.0 adds the connection type <em>Composition</em>, marked as the <a href="./metamodel-editing#composition">composition</a> of the hierarchy of components. Version 1.2.0 adds the two system-defined viewpoints <em>Application Landscape</em> and <em>Technology Landscape</em> in ArchiMate (see <a href="#viewpoints-in-packages">Viewpoints in packages</a>). Version 1.1.0 brought German labels for its entity types, <em>Status</em> and its values, and English labels for the values (see <a href="./metamodel-editing#translating-labels">Translating labels</a>). An instance that imported an earlier version receives the labels and viewpoints by importing the package again.</p><p>While the instance has no entity type, the start page shows <em>Import starter configuration</em> to a person with <code>metamodel:write</code>. Choose <em>Import</em> next to the package; the page confirms how many entity types are now available.</p>`,6),i(d,{name:`starter-import`,alt:`Start page with the starter configuration ready for import`}),o[1]||=t('<p>Through the API:</p><div class="language-bash" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]}&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/metamodel/starter-packages&quot;</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">                    # list with summary</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]}&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/metamodel/starter-packages/oea-starter-togaf-classic/import&quot;</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]}&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/metamodel/metatypes&quot;</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">                                       # imported entity types</span></span></code></pre></div><h2 id="import-your-own-package" tabindex="-1">Import your own package <a class="header-anchor" href="#import-your-own-package" aria-label="Permalink to “Import your own package”">​</a></h2><p>Packages of your own use the same JSON format (<code>MetamodelPackage</code>, with <code>packageId</code>, <code>packageVersion</code>, <code>publisher</code> and stable UUIDs per element). Import them with <code>POST /metamodel/import</code>:</p><ul><li>A package is imported completely or not at all. Imported content gets the scope <code>imported</code> and the package as origin.</li><li>Importing the same package again updates its own content. Content of another package or of your organization is never overwritten; the answer is <code>409</code> with the problem type <code>urn:oea:problem:package-conflict</code> and the list of conflicts in <code>conflictList</code>, and nothing of the package is stored.</li><li>A package can name a base type for an entity type (<code>baseMetatypeId</code>): an entity type of the same package or a built-in one. Your own properties on its entity types are kept or removed according to the re-import setting (see <a href="./metamodel-editing">Editing the metamodel</a>).</li><li>Packages larger than <code>oea.metamodel.import.max-size</code> (default 10 MB) are rejected with <code>413</code>; faulty JSON or content that does not match the format with <code>422</code> and the location of the problem.</li><li>A package can bring labels per language in <code>i18nBundles</code>, keyed as in <a href="./metamodel-editing#translating-labels">Translating labels</a>, but only for its own elements. A re-import replaces them; your own labels stay.</li><li>The strategy <code>replace</code> and shape assignments are not supported yet (<code>422</code>).</li></ul><p>Every import writes the audit events <code>metamodel.package-imported</code> and <code>metamodel.metatype-imported</code> with one batch ID.</p><h2 id="composition-in-packages" tabindex="-1">Composition in packages <a class="header-anchor" href="#composition-in-packages" aria-label="Permalink to “Composition in packages”">​</a></h2><p>A connection type of a package may carry <code>isComposition: true</code>; a package has at most one. The import is refused when the instance already has another marked connection type. A re-import of the same package moves or removes the mark with the package.</p><h2 id="layers-in-packages" tabindex="-1">Layers in packages <a class="header-anchor" href="#layers-in-packages" aria-label="Permalink to “Layers in packages”">​</a></h2><p>A package can bring architecture layers in <code>architectureLayers</code>: each with a stable <code>id</code>, a <code>name</code> of up to 100 characters and an optional <code>sortOrder</code>. The entity types of the package refer to them by <code>architectureLayerId</code>. The import installs them as read-only layers with the package as origin (see <a href="./metamodel-editing#layers">Layers</a>).</p><ul><li>A package has at most 20 layers, and together with the layers of your organization the instance has at most 20 (<code>422</code> otherwise). Names are unique within the package regardless of case; an entity type that refers to a layer outside the package is rejected with <code>422</code>.</li><li>A layer whose ID or name belongs to a layer of your organization or of another package answers <code>409</code> with <code>package-conflict</code>, and nothing is imported.</li><li>New layers are placed behind the existing ones in the order of <code>sortOrder</code>; layers that are already there keep their position.</li><li>Importing the same package again updates its layers. A layer the new version no longer has is deleted, and every entity type that had it – also those of your organization – loses its layer. Layers of your organization are kept.</li><li>The import result counts the created, updated and deleted layers (<code>layersCreated</code>, <code>layersUpdated</code>, <code>layersDeleted</code>) and the entity types that lost a layer (<code>layerAssignmentsCleared</code>). Labels for a layer go in <code>i18nBundles</code> under the key <code>architecture-layer.{id}.name</code>.</li></ul><h2 id="viewpoints-in-packages" tabindex="-1">Viewpoints in packages <a class="header-anchor" href="#viewpoints-in-packages" aria-label="Permalink to “Viewpoints in packages”">​</a></h2><p>A package can bring viewpoints in <code>viewpoints</code>: each with a stable <code>id</code>, <code>name</code>, optional <code>description</code>, <code>notation</code>, the allowed <code>metatypeIds</code> and <code>connectionTypeIds</code> (types of the package or of the instance), optional <code>mappings</code> and optional default <code>sizes</code> in pt (<code>metatypeId</code> with <code>width</code> and <code>height</code>, or <code>length</code>; see <a href="./metamodel-editing#viewpoints">Viewpoints</a>). The import installs them as system-defined, read-only viewpoints with the package as origin (see <a href="./metamodel-editing#viewpoints">Viewpoints</a>).</p><ul><li>A viewpoint has the same limits as one of your own: name up to 255 characters, description up to 1000, at most 500 entity types, 500 connection types, 1000 mappings and 1000 sizes, sizes of 1 to 2000 pt and colors as <code>#rrggbb</code>. A violation or an unknown type is rejected with <code>422</code> naming the viewpoint, a faulty size also <code>sizes</code>. <code>defaultWidth</code> and <code>defaultHeight</code> in a mapping are ignored.</li><li>Importing the same package again updates its viewpoints, also when one was renamed, and deletes those the package no longer contains, together with their <a href="./../usage/diagrams">diagrams</a>, the deleted ones included; the entities stay. Viewpoints of your organization or of another package are never overwritten: the same ID or name answers <code>409</code>.</li><li>The import result counts the created, updated and deleted viewpoints and, as <code>diagramsDeleted</code>, the diagrams that were deleted with them. A rejected import deletes nothing.</li></ul>',14)])}var l=r(s,[[`render`,c]]);export{o as __pageData,l as default};